// Parse Meta WhatsApp Cloud API payload
const body = $input.first().json.body || {};

// Handle status updates (ignore them)
const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value || {};

// Check if this is a message or just a status update
if (!value.messages || value.messages.length === 0) {
  console.log('No messages - status update, skipping');
  return [];
}

const messages = value.messages || [];
const contacts = value.contacts || [];

const message = messages[0] || {};
const contact = contacts[0] || {};

// Filter out reactions, read receipts, etc.
const ignoredTypes = ['reaction', 'read', 'delivery', 'sent'];
if (ignoredTypes.includes(message.type)) {
  console.log(`Ignoring message type: ${message.type}`);
  return [];
}

// Extract phone number (remove + prefix)
const phone = (message.from || '').replace(/^\+/, '');

// Get message content based on type
let messageText = '';
const messageType = message.type || 'text';

if (messageType === 'text') {
  messageText = message.text?.body || '';
} else if (messageType === 'audio') {
  // For audio, we'd need transcription - for now just note it
  messageText = '[Voice message received - transcription needed]';
} else if (messageType === 'image') {
  messageText = message.image?.caption || '[Image received]';
} else if (messageType === 'document') {
  messageText = message.document?.caption || '[Document received]';
} else if (messageType === 'contacts') {
  const sharedContacts = message.contacts || [];
  if (sharedContacts.length > 0) {
    const contactInfo = sharedContacts.map(c => {
      const name = c.name?.formatted_name || 'Unknown';
      const phones = c.phones?.map(p => p.phone).join(', ') || 'No phone';
      return `${name} (${phones})`;
    }).join('; ');
    messageText = `[Contact shared: ${contactInfo}]`;
  }
} else {
  messageText = `[${messageType} received]`;
}

console.log('Parsed message:', { phone, messageText, messageType });

return {
  json: {
    phone: phone,
    message: messageText,
    profile_name: contact.profile?.name || '',
    message_id: message.id || '',
    message_type: messageType,
    timestamp: new Date().toISOString()
  }
};
